import os as _os
ROOT = _os.path.dirname(_os.path.dirname(_os.path.abspath(__file__)))
DS = _os.path.join(ROOT, 'design-system')
CACHE = _os.path.join(ROOT, 'tools', '.cache')
from playwright.sync_api import sync_playwright
tok=open(_os.path.join(CACHE,'tokens.css')).read(); css=open(_os.path.join(DS,'components','bundle.css')).read(); js=open(_os.path.join(DS,'components','bundle.js')).read()
R=[]
def ok(c,m): R.append(c); print(('PASS ' if c else 'FAIL ')+m)
def load(pg, comp, theme='dark'):
    src=open(_os.path.join(DS,'components',comp,'preview.html')).read()
    html=src.replace('<html lang','<html data-theme="%s" lang'%theme,1).replace('<head>','<head><style>'+tok+'</style><style>'+css+'</style><script>'+js+'</script>',1)
    pg.set_content(html); pg.wait_for_timeout(300)
with sync_playwright() as p:
    b=p.chromium.launch()
    pg=b.new_page(viewport={'width':1000,'height':700}); load(pg,'SegmentedControl')
    it=pg.locator('[aria-label="Compare mode"] .lg-segmented__item')
    it.nth(2).focus(); pg.keyboard.press('ArrowRight')
    ok(it.nth(3).get_attribute('aria-checked')=='true' and pg.evaluate('document.activeElement.textContent')=='Swipe','segmented ArrowRight selects and focuses next')
    pg.keyboard.press('Home'); ok(it.nth(0).get_attribute('aria-checked')=='true','segmented Home')
    ok([it.nth(i).get_attribute('tabindex') for i in range(4)]==['0','-1','-1','-1'],'segmented roving tabindex')
    s=pg.locator('[aria-label="States demo"] .lg-segmented__item'); s.nth(2).focus(); pg.keyboard.press('ArrowRight')
    ok(s.nth(0).get_attribute('aria-checked')=='true','segmented skips disabled item and wraps')
    it.nth(1).click(); x=pg.evaluate('getComputedStyle(document.querySelector("[aria-label=\\"Compare mode\\"] .lg-segmented__thumb")).getPropertyValue("--lg-thumb-x")').strip()
    w=pg.evaluate('document.querySelectorAll("[aria-label=\\"Compare mode\\"] .lg-segmented__item")[1].offsetLeft')
    ok(x==f'{w}px', f'thumb follows selection ({x} vs {w}px)')
    ok(pg.evaluate('getComputedStyle(document.querySelector("[aria-label=\\"Compare mode\\"]")).backgroundColor')!='rgba(0, 0, 0, 0)','segmented track painted')
    pg.close()
    pg=b.new_page(viewport={'width':1340,'height':900}); load(pg,'Modal')
    pg.click('[data-lg-open="#live-sheet"]'); pg.wait_for_timeout(450)
    ok(pg.evaluate('document.getElementById("live-sheet").matches(":modal")'),'sheet opens modal')
    r=pg.evaluate('(()=>{const d=document.getElementById("live-sheet").getBoundingClientRect();return [Math.round(innerHeight-d.bottom), Math.round(d.width)]})()')
    ok(r[0]==16 and r[1]==820, f'sheet anchored 16px from bottom, 820 wide ({r})')
    st=pg.evaluate('(()=>{const d=document.getElementById("live-sheet"),c=getComputedStyle(d);return [d.hasAttribute("data-expanded"), c.backgroundColor, c.backdropFilter, Math.round(d.offsetHeight)]})()')
    ok(st[0]==False and st[1]=='rgba(22, 21, 28, 0.94)' and 'blur' in st[2], f'partial-height sheet is thick glass ({st})')
    ok(pg.evaluate('getComputedStyle(document.documentElement).overflow')=='hidden','page scroll locked')
    pg.keyboard.press('Escape'); pg.wait_for_timeout(500)
    ok(not pg.evaluate('document.getElementById("live-sheet").open'),'Esc closes sheet')
    ok(pg.evaluate('document.activeElement.getAttribute("data-lg-open")')=='#live-sheet','focus returns to trigger')
    pg.close()
    pg=b.new_page(viewport={'width':390,'height':844}); load(pg,'Modal')
    pg.click('[data-lg-open="#live-sheet"]'); pg.wait_for_timeout(450)
    r=pg.evaluate('(()=>{const d=document.getElementById("live-sheet").getBoundingClientRect();return [Math.round(innerHeight-d.bottom), Math.round(d.width)]})()')
    ok(r==[8,374], f'mobile sheet inset 8px, width 374 ({r})')
    fb=pg.evaluate('getComputedStyle(document.querySelector("#live-sheet .lg-modal__footer")).flexDirection'); ok(fb=='column','mobile sheet footer stacks')
    pg.evaluate('document.querySelector("#live-sheet .lg-modal__body").insertAdjacentHTML("beforeend", `<div id=tall style="height:900px"></div>`)'); pg.wait_for_timeout(600)
    st=pg.evaluate('(()=>{const d=document.getElementById("live-sheet"),c=getComputedStyle(d);return [d.hasAttribute("data-expanded"), c.backgroundColor, c.backdropFilter, d.offsetHeight, parseFloat(c.maxHeight)]})()')
    ok(st[0] and st[1]=='rgb(23, 22, 28)' and st[2]=='none', f'sheet at full height turns opaque surface ({st})')
    pg.evaluate('tall.remove()'); pg.wait_for_timeout(600)
    st2=pg.evaluate('(()=>{const d=document.getElementById("live-sheet");return [d.hasAttribute("data-expanded"), d.offsetHeight]})()')
    ok(not st2[0], f'same sheet becomes translucent again when it no longer fills the screen ({st2})')
    pg.close()
    pg=b.new_page(viewport={'width':1040,'height':900}); load(pg,'Toolbar')
    tb=pg.locator('[aria-label="Edit"] .lg-btn')
    tb.nth(0).focus(); pg.keyboard.press('ArrowRight'); ok(pg.evaluate('document.activeElement.getAttribute("aria-label")')=='Redo','toolbar ArrowRight')
    pg.keyboard.press('ArrowLeft'); pg.keyboard.press('ArrowLeft'); ok(pg.evaluate('document.activeElement.getAttribute("aria-label")')=='More','toolbar wraps across groups')
    pg.locator('[aria-label="Grid"]').focus(); pg.keyboard.press('ArrowRight'); ok(pg.evaluate('document.activeElement.getAttribute("aria-label")')=='Share','toolbar skips disabled button into next group')
    ok(pg.evaluate('[...document.querySelectorAll("[aria-label=\\"Edit\\"] .lg-toolbar__group")].length')==3,'canvas toolbar has 3 separate glass groups')
    pg.evaluate('(()=>{const g=document.querySelector("[aria-label=\\"Edit\\"] .lg-toolbar__group:last-child"); g.querySelectorAll("button").forEach(b=>b.hidden=true)})()')
    ok(pg.evaluate('getComputedStyle(document.querySelector("[aria-label=\\"Edit\\"] .lg-toolbar__group:last-child")).display')=='none','group with every item hidden disappears (no empty glass)')
    ok(pg.evaluate('[...document.querySelectorAll("[aria-label=\\"Edit\\"] .lg-btn")].filter(b=>b.tabIndex===0).length')==1,'toolbar single tab stop')
    g=pg.locator('[aria-label="Grid"]'); g.click(); pg.mouse.move(5,5); pg.wait_for_timeout(350); ok(g.get_attribute('aria-pressed')=='true','toolbar toggle flips aria-pressed')
    bg=pg.evaluate('getComputedStyle(document.querySelector("[aria-label=\\"Grid\\"]")).backgroundColor'); ok(bg in ('rgb(238, 235, 244)',), f'pressed toggle is inverse ({bg})')
    ok(pg.evaluate('document.querySelector("[aria-label=\\"Play\\"]").closest("[data-tone]").getAttribute("data-theme")')=='dark','stage tone resolves to dark theme')
    ok(pg.locator('.lg-composer button[type=submit]').nth(0).is_disabled() and not pg.locator('.lg-composer button[type=submit]').nth(1).is_disabled(),'composer send disabled only when empty')
    pg.close()
    pg=b.new_page(viewport={'width':1240,'height':1300}, color_scheme='light'); load(pg,'FloatingNavbar','light')
    t=pg.locator('[aria-controls="m4"]')
    ok(t.is_visible(),'menu toggle visible in 390 frame')
    ok(not pg.locator('[aria-controls="m1"]').is_visible(),'menu toggle hidden at 1240')
    ok(pg.evaluate('getComputedStyle(document.querySelectorAll(".lg-navbar")[3].querySelectorAll(".lg-navbar__island")[1]).display')=='none','context island hidden < 744')
    ok(pg.evaluate('getComputedStyle(document.querySelector(".nv-mid .lg-navbar__crumb")).display')=='none','crumb hidden 744-1099')
    t.click(); ok(t.get_attribute('aria-expanded')=='true' and not pg.evaluate('document.getElementById("m4").hidden'),'mobile menu opens')
    pg.keyboard.press('Escape'); ok(pg.evaluate('document.getElementById("m4").hidden') and pg.evaluate('document.activeElement.getAttribute("aria-controls")')=='m4','Esc closes menu, focus back')
    tones=pg.evaluate('[...document.querySelectorAll(".lg-navbar")].map(n=>[...n.querySelectorAll(".lg-navbar__island")].map(i=>i.getAttribute("data-theme")))')
    ok(tones[3][0]=='dark' and tones[0][0] is None, f'islands over a dark section turn dark ({tones[3]}, {tones[0]})')
    ok(pg.evaluate('document.querySelectorAll(".lg-navbar")[1].hasAttribute("data-scrolled")'),'data-scroll-manual keeps scrolled state')
    op=pg.evaluate('getComputedStyle(document.querySelectorAll(".lg-navbar")[1].querySelector(".lg-scroll-edge")).opacity'); ok(op=='1', f'scroll edge visible when scrolled ({op})')
    pg.close()
    pg=b.new_page(viewport={'width':800,'height':600}, color_scheme='dark', reduced_motion='reduce'); load(pg,'GlassButton')
    ok(pg.evaluate('LiquidGlass.applyTheme()')=='dark','applyTheme follows system dark')
    ok(pg.evaluate('LiquidGlass.applyTheme({transparency:"reduce"})')=='dark-solid','reduce transparency -> dark-solid')
    ok(pg.evaluate('LiquidGlass.applyTheme({contrast:"more"})')=='dark-contrast','increase contrast -> dark-contrast')
    pg.evaluate('LiquidGlass.applyTheme({contrast:"auto",transparency:"auto",glass:"strong"})')
    ok(pg.evaluate('document.documentElement.dataset.glass')=='strong','glass strong sets data-glass')
    bl=pg.evaluate('getComputedStyle(document.querySelector(".lg-btn.lg-glass")).backdropFilter'); ok('32px' in bl, f'strong glass raises blur ({bl})')
    pg.evaluate('LiquidGlass.applyTheme({glass:"auto"})')
    ok(pg.evaluate('getComputedStyle(document.querySelector(".lg-btn[data-state=active]")).transform')=='none','reduced motion: no press scale')
    pg.evaluate('LiquidGlass.toast("Link copied", {timeout: 300})'); pg.wait_for_timeout(100)
    ok(pg.evaluate('(()=>{const t=document.querySelector(".lg-toast");return t && t.getAttribute("role")==="status" && t.textContent==="Link copied" && !t.hidden})()'),'toast shows in a status region')
    pg.wait_for_timeout(400); ok(pg.evaluate('document.querySelector(".lg-toast").hidden'),'toast hides after timeout')
    pg.evaluate('document.body.insertAdjacentHTML("beforeend", `<button id=t aria-controls=pp aria-expanded=false>t</button><div id=pp class="lg-menu lg-glass lg-glass--popover" hidden data-lg=panel><button class=lg-menu__item>a</button></div>`); LiquidGlass.init(document)')
    pg.click('#t'); ok(not pg.evaluate('pp.hidden') and pg.evaluate('t.getAttribute("aria-expanded")')=='true','panel finds trigger via aria-controls and opens')
    pg.keyboard.press('Escape'); ok(pg.evaluate('pp.hidden'),'Esc closes panel')
    pg.close()

    # ---------- GlassPanel: menu grows from its trigger ----------
    pg=b.new_page(viewport={'width':1140,'height':1000}); load(pg,'GlassPanel')
    pg.evaluate('document.body.insertAdjacentHTML("beforeend", `<div style="position:fixed;left:600px;top:300px"><button id=tt aria-controls=pm aria-expanded=false style="width:40px;height:40px">t</button><div id=pm class="lg-menu lg-glass" role=menu hidden data-lg=panel style="position:absolute;right:0;top:48px"><button class=lg-menu__item role=menuitem>a</button></div></div>`); LiquidGlass.init(document)')
    pg.click('#tt'); pg.wait_for_timeout(50)
    o=pg.evaluate('getComputedStyle(pm).getPropertyValue("--lg-origin").trim()'); to=pg.evaluate('getComputedStyle(pm).transformOrigin')
    exp=pg.evaluate('Math.round(tt.getBoundingClientRect().left+20-(pm.offsetParent.getBoundingClientRect().left+pm.offsetLeft))')
    ok(o==f'{exp}px 0px' and to.startswith(f'{exp}px'), f'menu transform-origin is the trigger ({o}, {to})')
    ok(pg.evaluate('getComputedStyle(pm).backgroundColor')=='rgba(22, 21, 28, 0.94)','a menu is thick glass even without lg-glass--popover')
    ok(pg.evaluate('[...document.querySelectorAll(".lg-menu__item")].filter(m=>m.offsetParent && !m.querySelector("svg") && m.closest("#pm")===null).length')==0,'every demo menu item has an icon')
    pg.close()
    # ---------- TabBar on a real scrolling page ----------
    page_html = f"""<!doctype html><html lang="zh-Hant-TW" data-theme="dark"><head><meta name=viewport content="width=device-width,initial-scale=1,viewport-fit=cover"><style>{tok}</style><style>{css}</style><script>{js}</script></head>
    <body style="margin:0;background:var(--canvas)">
    <header class="lg-navbar" data-lg="navbar"><div class="lg-scroll-edge" aria-hidden="true"></div><div class="lg-navbar__row">
      <div class="lg-navbar__island lg-glass"><a class="lg-navbar__brand lg-focusable" href="#" aria-label="Home"><span>Brand</span></a><span class="lg-nav-desktop"><nav class="lg-segmented" aria-label="Site"><a class="lg-segmented__item lg-navbar__link" href="#" aria-current="page">Home</a><a class="lg-segmented__item lg-navbar__link" href="#">Work</a><a class="lg-segmented__item lg-navbar__link" href="#">Shows</a></nav></span></div>
      <button class="lg-btn lg-btn--accent lg-nav-desktop" type="button">Contact Us</button><span class="lg-navbar__spacer"></span>
      <div class="lg-navbar__island lg-navbar__island--tight lg-glass"><button class="lg-btn lg-btn--plain lg-btn--icon lg-nav-desktop" type="button" aria-label="Search">s</button><button class="lg-btn lg-btn--plain lg-btn--icon lg-navbar__menu-toggle" type="button" aria-label="Menu" aria-expanded="false" aria-controls="mm">m</button></div>
    </div><div class="lg-navbar__menu lg-menu lg-glass lg-glass--popover" id="mm" hidden><a class="lg-menu__item" href="#">x</a></div></header>
    <main style="padding:68px 16px 120px">{''.join('<p style="height:120px;margin:0 0 16px;background:var(--surface);border-radius:16px">Content</p>' for _ in range(30))}
      <div class="lg-toolbar lg-toolbar--float" role="toolbar" aria-label="t" data-lg="toolbar"><div class="lg-toolbar__group lg-glass"><button class="lg-btn lg-btn--plain lg-btn--icon" type="button" aria-label="a">a</button><button class="lg-btn lg-btn--plain lg-btn--icon" type="button" aria-label="b">b</button></div></div>
    </main>
    <nav class="lg-tabbar" aria-label="Main tabs" data-lg="tabbar"><div class="lg-scroll-edge lg-scroll-edge--bottom" aria-hidden="true"></div><div class="lg-tabbar__tabs lg-glass"><a class="lg-tabbar__tab" href="#" aria-current="page"><span>Home</span></a><a class="lg-tabbar__tab" href="#"><span>Work</span></a><a class="lg-tabbar__tab" href="#"><span>Shows</span></a></div><button class="lg-tabbar__search lg-glass" type="button" aria-label="Search">s</button></nav>
    <script>LiquidGlass.init()</script></body></html>"""
    pg=b.new_page(viewport={'width':390,'height':844}); pg.set_content(page_html); pg.wait_for_timeout(200)
    tbar='document.querySelector(".lg-tabbar")'
    r=pg.evaluate(f'(()=>{{const t={tbar}.getBoundingClientRect();return [Math.round(innerHeight-t.bottom), Math.round(t.left), Math.round(innerWidth-t.right)]}})()')
    ok(r==[8,8,8], f'tab bar floats 8px from the bottom and sides ({r})')
    ok(pg.evaluate('getComputedStyle(document.documentElement).getPropertyValue("--lg-keyboard-inset").trim()')=='0px','keyboard inset tracked (0px with no keyboard)')
    sr=pg.evaluate('(()=>{const s=document.querySelector(".lg-tabbar__search").getBoundingClientRect(),t=document.querySelector(".lg-tabbar__tabs").getBoundingClientRect();return [s.left>t.right, Math.round(s.width)]})()')
    ok(sr[0] and sr[1]==56, f'search is a separate trailing circle ({sr})')
    pg.mouse.wheel(0,600); pg.wait_for_timeout(600)
    ok(pg.evaluate(f'{tbar}.hasAttribute("data-minimized")'),'tab bar minimizes on scroll down')
    w=pg.evaluate('Math.round(document.querySelector(".lg-tabbar__tabs").getBoundingClientRect().width)'); ok(w<=48, f'minimized tabs collapse to the current tab ({w}px)')
    pg.mouse.wheel(0,-200); pg.wait_for_timeout(250)
    ok(not pg.evaluate(f'{tbar}.hasAttribute("data-minimized")'),'tab bar expands on scroll up')
    pg.mouse.wheel(0,600); pg.wait_for_timeout(250); pg.focus('.lg-tabbar__tab[aria-current]')
    ok(not pg.evaluate(f'{tbar}.hasAttribute("data-minimized")'),'focus inside the tab bar restores it')
    ok(pg.evaluate('getComputedStyle(document.querySelector(".lg-tabbar .lg-scroll-edge")).opacity')=='1','bottom scroll edge shows while content is under the tab bar')
    ok(pg.evaluate('document.querySelector(".lg-navbar").hasAttribute("data-scrolled")'),'top scroll edge on while scrolled')
    pg.close()
    pg=b.new_page(viewport={'width':390,'height':844}, reduced_motion='reduce'); pg.set_content(page_html); pg.wait_for_timeout(200)
    ok(pg.evaluate('getComputedStyle(document.querySelector(".lg-tabbar__tabs")).transitionDuration')=='0s','reduced motion: tab bar resize does not animate')
    pg.close()

    # ---------- v3.2: fixes from the independent review ----------
    pg=b.new_page(viewport={'width':1440,'height':900}); load(pg,'ShowcaseDesktop')
    c=pg.evaluate('getComputedStyle(document.querySelector(".lg-progress--neutral > span")).backgroundColor')
    ok(c=='rgb(238, 235, 244)', f'neutral progress in the nav is ink, not accent ({c})')
    acc=pg.evaluate('[...document.querySelectorAll(".lg-btn--accent")].filter(b=>b.offsetParent && !b.disabled).map(b=>b.textContent.trim())')
    ok(len(acc)==2, f'one accent in the nav + one on screen ({acc})')
    snd=pg.evaluate('getComputedStyle(document.querySelector(".lg-composer button[type=submit]")).backgroundColor')
    ok(snd!='rgb(167, 139, 250)', f'empty composer: Send is not an accent fill ({snd})')
    ok(pg.evaluate('getComputedStyle(document.querySelector(".sc-dock")).backdropFilter')=='none' and not pg.evaluate('document.querySelector(".sc-dock").matches(".lg-glass")'),'contact sheet dock is content: opaque surface, not glass')
    ok(pg.evaluate('document.querySelectorAll("[data-refract]").length')<=3, 'at most 3 refracting elements')
    pg.close()
    pg=b.new_page(viewport={'width':390,'height':844}); pg.set_content(page_html.replace('<main style="padding:68px 16px 120px">','<main style="padding:0 0 120px"><section data-surface-tone="dark" style="height:2000px;background:#111"></section>')); pg.wait_for_timeout(300)
    t=pg.evaluate('[document.querySelector(".lg-tabbar__tabs").getAttribute("data-tone"), document.querySelector(".lg-tabbar__search").getAttribute("data-tone")]')
    ok(t==['dark','dark'], f'tab bar over a dark section turns dark glass ({t})')
    pg.evaluate('LiquidGlass.TabBar(document.querySelector(".lg-tabbar")).setMinimized(true)'); pg.wait_for_timeout(450)
    nm=pg.evaluate('(()=>{const a=document.querySelector(".lg-tabbar__tab[aria-current]"); const s=a.querySelector("span"); return [a.textContent.trim(), getComputedStyle(s).display, Math.round(s.getBoundingClientRect().width)]})()')
    ok(nm[0]=='Home' and nm[1]!='none' and nm[2]<=1, f'minimized current tab keeps its name, hidden visually ({nm})')
    pg.close()
    pg=b.new_page(viewport={'width':1270,'height':1450}); load(pg,'FloatingNavbar','light-contrast')
    ring=pg.evaluate('getComputedStyle(document.querySelector(".lg-tabbar__tab[aria-current]")).boxShadow')
    ok('2px' in ring, f'high contrast: current tab has a 2px ring ({ring})')
    pg.close()
    pg=b.new_page(viewport={'width':1270,'height':1450}); load(pg,'FloatingNavbar','light')
    tn=pg.evaluate('(()=>{const f=document.querySelector(".nv-phone"); return [...f.querySelectorAll(".lg-navbar__island, .lg-tabbar__tabs, .lg-tabbar__search")].filter(e=>e.offsetWidth).map(e=>e.getAttribute("data-tone"))})()')
    ok(all(x=='dark' for x in tn), f'light theme, phone over the dark hero: islands and tab bar all dark ({tn})')
    top=pg.evaluate('[...document.querySelector(".nv-1440 .lg-navbar").querySelectorAll(".lg-segmented__item.lg-navbar__link")].map(a=>a.textContent.trim())')
    tabs=pg.evaluate('[...document.querySelector(".nv-phone .lg-tabbar").querySelectorAll(".lg-tabbar__tab")].map(a=>a.textContent.trim())')
    ok(top==tabs, f'tab bar carries the same destinations as the desktop islands ({top} / {tabs})')
    pg.close()
    pg=b.new_page(viewport={'width':390,'height':844}); load(pg,'Modal')
    pg.click('[data-lg-open="#live-sheet"]'); pg.wait_for_timeout(450)
    pg.evaluate('document.querySelector("#live-sheet .lg-modal__body").insertAdjacentHTML("beforeend", `<div id=tall style="height:900px"></div>`)'); pg.wait_for_timeout(600)
    r=pg.evaluate('(()=>{const d=document.getElementById("live-sheet").getBoundingClientRect();return [Math.round(d.width), Math.round(innerHeight-d.bottom)]})()')
    ok(r==[390,0], f'mobile: full-height sheet meets the screen edges ({r})')
    pg.close()
    # ---------- no horizontal scrolling at any width ----------
    bad=[]
    for wd in (320,390,600,744,900,1024,1100,1280,1440,1920):
        pg=b.new_page(viewport={'width':wd,'height':900}); pg.set_content(page_html); pg.wait_for_timeout(150)
        sw=pg.evaluate('document.documentElement.scrollWidth'); tabs=pg.evaluate('getComputedStyle(document.querySelector(".lg-tabbar")).display'); desk=pg.evaluate('getComputedStyle(document.querySelector(".lg-navbar .lg-nav-desktop")).display')
        if sw>wd: bad.append((wd,sw))
        if (wd<744) != (tabs!='none'): bad.append((wd,'tabbar',tabs))
        if (wd<744) != (desk=='none'): bad.append((wd,'nav-desktop',desk))
        pg.close()
    ok(not bad, f'320–1920: no horizontal scroll; tab bar only < 744, top links only ≥ 744 ({bad})')
    import re as _re
    for comp in ('FloatingNavbar','GlassButton','SegmentedControl','Toolbar','GlassPanel','Modal','Patterns','Materials','ShowcaseDesktop','ShowcaseMobile','Cover'):
        _m=_re.search(r'width=(\d+)', open(_os.path.join(DS,'components',comp,'preview.html')).readline()); wd=int(_m.group(1)) if _m else 1200
        pg=b.new_page(viewport={'width':wd,'height':900}); load(pg,comp)
        sw=pg.evaluate('document.documentElement.scrollWidth'); ok(sw<=wd, f'{comp} card fits its width ({sw} ≤ {wd})'); pg.close()
    b.close()
print(sum(R),'/',len(R))
import sys as _sys
_sys.exit(0 if all(R) else 1)
